<script setup lang="ts">
import { computed, onMounted, ref, watch, type Component } from 'vue'
import { ArrowRight, BarChart3, CircleAlert, HandCoins, Package, Printer, ReceiptText, RefreshCw, ShoppingCart, TriangleAlert, TrendingUp } from 'lucide-vue-next'
import KpiCard from '../components/KpiCard.vue'
import SectionPanel from '../components/SectionPanel.vue'
import WorkspaceBottomActions from '../components/WorkspaceBottomActions.vue'
import WorkspaceStickyStack from '../components/WorkspaceStickyStack.vue'
import StatusBadge from '../components/StatusBadge.vue'
import { reportsApi, type DashboardRecord } from '../api/reports'
import { formatMoney } from '../utils/currency'
import { formatDate, formatDateTime, currentCanonicalDate } from '../utils/date'
const props=defineProps<{currencyUnit:'Rial'|'Toman'}>();const emit=defineEmits<{navigate:[view:string];newOrder:[];notify:[message:string]}>();const data=ref<DashboardRecord|null>(null);const loading=ref(false);const error=ref('');const end=currentCanonicalDate();const start=new Date(Date.now()-30*86400000).toISOString().slice(0,10);const money=(v:number)=>formatMoney(v,props.currencyUnit)
async function load(){loading.value=true;try{data.value=await reportsApi.dashboard(start,end)}catch(e){error.value=String(e)}finally{loading.value=false}};onMounted(load);watch(()=>props.currencyUnit,load);const attention=computed(()=>data.value?.attention??[])
</script>
<template><div class="dashboard-view"><WorkspaceStickyStack><header class="workspace-heading"><div><p class="eyebrow">{{data?.startDate||start}} → {{data?.endDate||end}}</p><h1>Good morning</h1><p class="heading-description">Here is what needs your attention today.</p></div><div class="heading-actions"><button class="button button-secondary" type="button" @click="load"><RefreshCw :size="15"/> Refresh</button><button class="button button-primary" type="button" @click="emit('newOrder')">New order</button></div></header></WorkspaceStickyStack><p v-if="error" class="form-error">{{error}}</p><div class="dashboard-content"><section class="kpi-grid"><KpiCard :value="money(data?.revenueRial||0)" detail="Posted invoices in period" title="Sales" :trend="loading?'Loading':'Persisted'" :icon="TrendingUp" accent="blue"/><KpiCard :value="money(data?.grossProfitRial||0)" detail="Journal-derived P&L" title="Gross profit" trend="Journal" :icon="BarChart3" accent="green"/><KpiCard :value="money(data?.receivableRial||0)" :detail="`${data?.openInvoiceCount||0} open invoices`" title="Receivables" trend="Authoritative" :icon="HandCoins" accent="amber"/><KpiCard :value="money(data?.payableRial||0)" detail="Journal-derived" title="Payables" trend="Supplier" :icon="ReceiptText" accent="red"/></section><section class="dashboard-grid dashboard-grid-primary"><SectionPanel title="Needs attention" subtitle="Due obligations and operational exceptions"><div class="alert-list"><button v-for="item in attention" :key="`${item.kind}-${item.detail}`" class="alert-row" type="button" @click="emit('notify',item.detail)"><span class="alert-icon tone-red"><CircleAlert :size="15"/></span><span class="alert-content"><span class="alert-label">{{item.label}}</span><span class="alert-detail">{{item.detail}}<template v-if="item.date"> · {{formatDate(item.date)}}</template></span></span><span class="alert-amount">{{item.amountRial?money(item.amountRial):'—'}}</span></button><p v-if="!attention.length" class="empty-table">No attention items from persisted data.</p></div></SectionPanel><SectionPanel title="Production queue" subtitle="Persisted active jobs"><div class="table-wrap"><table class="data-table"><thead><tr><th>Order</th><th>Customer</th><th>Service</th><th>Status</th></tr></thead><tbody><tr v-for="job in data?.production" :key="job.id"><td>{{job.orderNumber||job.id}}</td><td>{{job.customer||'—'}}</td><td>{{job.service}}</td><td><StatusBadge :label="job.status" tone="blue"/></td></tr><tr v-if="!data?.production?.length"><td colspan="4" class="empty-table">No active production jobs.</td></tr></tbody></table></div></SectionPanel></section><section class="dashboard-grid dashboard-grid-secondary"><SectionPanel title="Low stock" subtitle="Movement-derived availability"><div class="stock-list"><div v-for="item in data?.lowStock" :key="item.id" class="stock-row"><TriangleAlert class="stock-indicator tone-amber" :size="15"/><span class="stock-name">{{item.name}}</span><span class="stock-available">{{item.availableUnits/1000000}} {{item.unit}}</span><span class="stock-threshold">Reorder at {{item.reorderLevelUnits/1000000}}</span></div><p v-if="!data?.lowStock?.length" class="empty-table">No low-stock materials.</p></div></SectionPanel><SectionPanel title="Recent payments" subtitle="Latest persisted financial activity"><div class="transaction-list"><div v-for="item in data?.recentActivity" :key="item.id" class="transaction-row"><span class="transaction-icon tone-green"><HandCoins :size="15"/></span><span class="transaction-content"><span class="transaction-title">{{item.label}}</span><span class="transaction-party">{{item.detail}} · {{formatDateTime(item.date)}}</span></span><span class="transaction-value" :class="{'value-positive':item.direction==='incoming'}">{{money(item.amountRial)}}</span></div><p v-if="!data?.recentActivity?.length" class="empty-table">No payments recorded.</p></div></SectionPanel></section></div><WorkspaceBottomActions class="quick-actions"><div><p class="section-kicker">Quick actions</p><p class="quick-actions-help">Jump into real workflows.</p></div><div class="quick-action-buttons"><button class="quick-action" type="button" @click="emit('newOrder')">New order</button><button class="quick-action" type="button" @click="emit('navigate','Production')"><Printer :size="16"/> Production</button><button class="quick-action" type="button" @click="emit('navigate','Purchases')"><ShoppingCart :size="16"/> Purchase</button><button class="quick-action" type="button" @click="emit('navigate','Reports')"><BarChart3 :size="16"/> Reports</button></div></WorkspaceBottomActions></div></template>
